from __future__ import annotations

CONTROL_CSS = '''<style>
:root{--bg:#0b1020;--panel:#121a2c;--panel2:#18243b;--line:#283754;--text:#f3f6ff;--muted:#8d9bb7;--cyan:#67d5e8;--green:#5ee1a4;--gold:#f4c96b;--purple:#9e8cff;--red:#f07883}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,#314c82 0,transparent 38%),radial-gradient(circle at 0 100%,#183b43 0,transparent 32%),var(--bg);color:var(--text);font-family:Tahoma,Arial,sans-serif}.shell{display:flex;min-height:100vh}.side{width:260px;background:#0d1425e8;border-left:1px solid var(--line);padding:25px 16px;display:flex;flex-direction:column;backdrop-filter:blur(20px)}.brand{display:flex;align-items:center;gap:11px;padding:4px 10px 32px}.brand-mark{display:grid;place-items:center;width:39px;height:39px;border-radius:12px;background:linear-gradient(135deg,var(--cyan),var(--purple));font-size:22px;font-weight:bold}.brand b{display:block}.brand small{color:var(--muted);font-size:9px;letter-spacing:2px}.nav{display:flex;align-items:center;gap:12px;width:100%;border:0;background:transparent;color:var(--muted);padding:13px 14px;border-radius:11px;text-align:right;cursor:pointer;font-size:13px;margin:2px 0;transition:.2s}.nav:hover,.nav.active{background:linear-gradient(90deg,#243655,#1b2944);color:var(--text);transform:translateX(-3px)}.nav i{margin-right:auto;background:var(--red);border-radius:50%;width:7px;height:7px}.side-foot{margin-top:auto;color:var(--muted);font-size:12px;padding:15px 10px}.pulse{display:inline-block;width:8px;height:8px;background:var(--green);border-radius:50%;box-shadow:0 0 0 5px #5ee1a420;margin-left:6px}.logout{display:block;border:0;background:transparent;color:var(--muted);padding:14px 0 0;cursor:pointer}.main{flex:1;min-width:0;padding:30px 40px;max-width:1500px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:34px}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--cyan)}h1,h2,h3{margin:7px 0}h1{font-size:27px}.top-actions{display:flex;align-items:center;gap:14px;color:var(--muted)}.icon-btn,.avatar{border:1px solid var(--line);background:var(--panel);color:var(--text);border-radius:10px;padding:9px 13px;cursor:pointer}.avatar{border-radius:50%;background:linear-gradient(135deg,var(--cyan),var(--purple));border:0}.hero{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(110deg,#1a2947,#18263eaa);border:1px solid var(--line);border-radius:22px;padding:27px 32px;margin-bottom:20px;overflow:hidden}.hero-orb{width:92px;height:92px;border-radius:30px;display:grid;place-items:center;background:linear-gradient(135deg,#67d5e8,#9e8cff);font-size:43px;font-weight:bold;box-shadow:0 0 50px #67d5e844;animation:float 5s ease-in-out infinite}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px}.stat,.panel,.bank-card,.channel,.ticket{background:#121a2cee;border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:0 12px 35px #05091440}.stat{position:relative;overflow:hidden}.stat span,.stat small{display:block;color:var(--muted);font-size:12px}.stat strong{display:block;font-size:28px;margin:13px 0}.cyan{color:var(--cyan)}.green{color:var(--green)}.gold{color:var(--gold)}.purple{color:var(--purple)}.two-col,.system-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:16px}.quick{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.quick button,.primary{background:linear-gradient(135deg,#4d7dff,#826cf4);border:0;color:white;border-radius:9px;padding:12px;cursor:pointer}.toolbar{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px}.counter,.tag{display:inline-block;padding:5px 9px;border-radius:8px;background:#24314b;color:var(--muted);font-size:11px}.tag.on{background:#5ee1a41b;color:var(--green)}.tag.off{background:#f078831b;color:var(--red)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:15px 10px;text-align:right;border-bottom:1px solid var(--line);font-size:13px;white-space:nowrap}th{color:var(--muted);font-size:11px}td small{display:block;color:var(--muted);font-size:10px;margin-top:5px}.mini{border:1px solid var(--line);background:#1d2a43;color:var(--text);border-radius:7px;padding:7px 9px;cursor:pointer;margin-left:4px;font-size:11px}.mini.danger{color:var(--red)}.card-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:15px}.bank-card{background:linear-gradient(135deg,#1d3557,#2a2452);min-height:170px;display:flex;flex-direction:column;gap:13px}.bank-top{display:flex;justify-content:space-between}.bank-card strong{font-size:20px;letter-spacing:2px;text-align:center;margin:14px 0}.bank-card small,.channel small,.channel a{color:var(--muted);display:block}.card-actions{margin-top:auto}.channel{display:flex;flex-direction:column;gap:11px}.channel a{color:var(--cyan)}.ticket-list{display:grid;gap:12px}.ticket-head{display:flex;justify-content:space-between}.ticket-head span{color:var(--muted);font-size:11px}.ticket p{color:var(--muted);line-height:1.8}.ticket.closed{opacity:.6}.permissions{font-size:11px;color:var(--cyan)}.menu-editor{display:grid;gap:11px}.menu-row{display:grid;grid-template-columns:25px 90px 1fr 130px 70px;align-items:center;gap:10px;background:var(--panel);border:1px solid var(--line);padding:12px;border-radius:11px}.drag{color:var(--muted)}input,textarea,select{width:100%;background:#0d1526;color:var(--text);border:1px solid var(--line);border-radius:8px;padding:11px;margin:6px 0 13px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.wide{width:100%;margin-top:8px}.modal-back{position:fixed;inset:0;background:#030713b8;backdrop-filter:blur(8px);display:grid;place-items:center;padding:20px;z-index:5}.modal{position:relative;width:min(500px,100%);background:#17233a;border:1px solid #405477;border-radius:18px;padding:25px;box-shadow:0 25px 100px #0008}.modal-close{position:absolute;left:17px;top:14px;border:0;background:transparent;color:var(--muted);font-size:25px;cursor:pointer}.empty{display:grid;place-items:center;gap:8px;padding:50px;color:var(--muted);text-align:center}.toast{position:fixed;left:35px;bottom:25px;padding:13px 18px;border-radius:10px;background:#182942;border:1px solid var(--line);z-index:8}.toast.ok{color:var(--green)}.toast.bad{color:var(--red)}@keyframes float{50%{transform:translateY(-8px) rotate(3deg)}}@media(max-width:900px){.side{width:76px;padding:20px 10px}.brand div,.nav span,.side-foot{display:none}.nav{justify-content:center}.main{padding:22px}.stat-grid{grid-template-columns:repeat(2,1fr)}.system-grid,.two-col{grid-template-columns:1fr}.menu-row{grid-template-columns:20px 1fr}}@media(max-width:600px){.main{padding:16px}.top{margin-bottom:20px}.hero-orb{display:none}.stat{padding:12px}.stat strong{font-size:20px}.toolbar{align-items:start;gap:10px;flex-direction:column}.menu-row{grid-template-columns:20px 1fr}.menu-row input,.menu-row select{grid-column:span 2}}
</style>'''


def control_body() -> str:
    return '''<div class="shell"><aside class="side"><div class="brand"><span class="brand-mark">N</span><div><b>Nova Store</b><small>CONTROL CENTER</small></div></div><nav><button class="nav active" data-view="dashboard">⌂ <span>داشبورد</span></button><button class="nav" data-view="products">▣ <span>محصولات</span></button><button class="nav" data-view="cards">▤ <span>کارت‌های پرداخت</span></button><button class="nav" data-view="users">♙ <span>کاربران</span></button><button class="nav" data-view="support">◌ <span>پشتیبانی</span><i id="supportBadge"></i></button><button class="nav" data-view="admins">♛ <span>مدیران</span></button><button class="nav" data-view="channels">◉ <span>عضویت اجباری</span></button><button class="nav" data-view="menu">✦ <span>طراحی منو</span></button><button class="nav" data-view="system">⚙ <span>سیستم و بکاپ</span></button></nav><div class="side-foot"><span class="pulse"></span> سیستم آنلاین<button class="logout" onclick="logout()">خروج امن</button></div></aside><main class="main"><header class="top"><div><span class="eyebrow">NOVA / ADMIN</span><h1 id="viewTitle">داشبورد</h1></div><div class="top-actions"><span id="clock"></span><button class="icon-btn" onclick="refreshView()">↻</button><button class="avatar">M</button></div></header><div id="toast"></div><section id="view" class="view"></section></main></div><script>
const $=s=>document.querySelector(s), api=(u,o={})=>fetch(u,{headers:{'Content-Type':'application/json',...(o.headers||{})},...o}).then(async r=>{if(!r.ok)throw Error((await r.json()).detail||'خطای ناشناخته');return r.json()}), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])), money=n=>Number(n||0).toLocaleString('fa-IR'), toast=(m,ok=true)=>{const e=$('#toast');e.innerHTML=`<div class="toast ${ok?'ok':'bad'}">${ok?'✓':'!'} ${esc(m)}</div>`;setTimeout(()=>e.innerHTML='',3500)}, empty=t=>`<div class="empty"><div class="empty-icon">✦</div><b>${t}</b><small>هنوز داده‌ای برای نمایش وجود ندارد</small></div>`;
let current='dashboard';document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');current=b.dataset.view;$('#viewTitle').textContent=b.innerText;load(current)});function load(v=current){const f={dashboard:dashboard,products:products,cards:cards,users:users,support:support,admins:admins,channels:channels,menu:menu,system:system}[v];if(f)f().catch(e=>toast(e.message,false))}function refreshView(){load()};setInterval(()=>$('#clock').textContent=new Date().toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'}),1000);
async function dashboard(){let d=await api('/api/stats');$('#view').innerHTML=`<div class="hero"><div><span class="eyebrow">GOOD TO SEE YOU</span><h2>مرکز فرمان فروشگاه</h2><p>همه‌چیز تحت کنترل است. از اینجا فروشگاهت را مدیریت کن.</p></div><div class="hero-orb">N</div></div><div class="stat-grid"><div class="stat cyan"><span>کاربران</span><strong>${money(d.users)}</strong><small>ثبت‌نام‌شده</small></div><div class="stat green"><span>محصولات فعال</span><strong>${money(d.products)}</strong><small>در ویترین</small></div><div class="stat gold"><span>کارت‌های فعال</span><strong>${money(d.cards)}</strong><small>روش پرداخت</small></div><div class="stat purple"><span>ارزش موجودی</span><strong>${money(d.inventory)}</strong><small>تومان</small></div></div><div class="two-col"><div class="panel"><div class="panel-head"><div><span class="eyebrow">QUICK ACTIONS</span><h3>دسترسی سریع</h3></div></div><div class="quick"><button onclick="go('products')">＋ محصول جدید</button><button onclick="go('broadcast')">↗ پیام همگانی</button><button onclick="go('system')">⇩ دریافت بکاپ</button><button onclick="go('support')">◌ صندوق پشتیبانی</button></div></div><div class="panel spotlight"><span class="eyebrow">LIVE STATUS</span><h3>فروشگاه آماده‌ی سرویس است</h3><p><i class="pulse"></i> ربات و پنل وب هم‌زمان آنلاین هستند.</p><div class="line"><span></span></div></div></div>`}function go(v){document.querySelector(`[data-view="${v}"]`)?.click();if(v==='broadcast')broadcast()}
async function products(){let a=await api('/api/products');$('#view').innerHTML=`<div class="toolbar"><div><span class="eyebrow">CATALOG</span><h2>محصولات</h2></div><button class="primary" onclick="productForm()">＋ افزودن محصول</button></div><div class="panel table-wrap"><table><thead><tr><th>محصول</th><th>قیمت</th><th>موجودی</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${a.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.description).slice(0,45)}</small></td><td>${money(x.price)} تومان</td><td><span class="stock ${x.stock<3?'low':''}">${x.stock}</span></td><td><span class="tag ${x.is_active?'on':'off'}">${x.is_active?'فعال':'غیرفعال'}</span></td><td><button class="mini" onclick='productForm(${JSON.stringify(x)})'>ویرایش</button><button class="mini" onclick="toggleProduct(${x.id})">${x.is_active?'خاموش':'فعال'}</button><button class="mini danger" onclick="removeProduct(${x.id})">حذف</button></td></tr>`).join('')||`<tr><td colspan="5">${empty('محصولی ثبت نشده')}</td></tr>`}</tbody></table></div>`}function productForm(x={}){modal(`<h2>${x.id?'ویرایش محصول':'محصول جدید'}</h2><label>نام محصول<input id="fName" value="${esc(x.name)}"></label><label>توضیحات<textarea id="fDesc">${esc(x.description)}</textarea></label><div class="form-row"><label>قیمت<input id="fPrice" type="number" value="${x.price||0}"></label><label>موجودی<input id="fStock" type="number" value="${x.stock||0}"></label></div><button class="primary wide" onclick="saveProduct(${x.id||0})">ذخیره محصول</button>`)}async function saveProduct(id){await api(id?'/api/products/'+id:'/api/products',{method:id?'PUT':'POST',body:JSON.stringify({name:$('#fName').value,description:$('#fDesc').value,price:+$('#fPrice').value,stock:+$('#fStock').value,is_active:true})});closeModal();toast('محصول ذخیره شد');products()}async function toggleProduct(id){await api('/api/products/'+id+'/toggle',{method:'POST'});toast('وضعیت محصول تغییر کرد');products()}async function removeProduct(id){if(confirm('حذف کامل محصول انجام شود؟')){await api('/api/products/'+id,{method:'DELETE'});toast('محصول حذف شد');products()}}
async function cards(){let a=await api('/api/cards');$('#view').innerHTML=`<div class="toolbar"><div><span class="eyebrow">PAYMENTS</span><h2>کارت‌های بانکی</h2></div><button class="primary" onclick="cardForm()">＋ افزودن کارت</button></div><div class="card-grid">${a.map(x=>`<article class="bank-card ${x.is_active?'':'muted'}"><div class="bank-top"><b>${esc(x.title)}</b><span class="tag ${x.is_active?'on':'off'}">${x.is_active?'فعال':'غیرفعال'}</span></div><strong>${esc(x.number)}</strong><small>${esc(x.holder)}</small><div class="card-actions"><button class="mini" onclick='cardForm(${JSON.stringify(x)})'>ویرایش</button><button class="mini" onclick="toggleCard(${x.id})">${x.is_active?'غیرفعال':'فعال'}</button><button class="mini danger" onclick="removeCard(${x.id})">حذف</button></div></article>`).join('')||empty('کارتی ثبت نشده')}</div>`}function cardForm(x={}){modal(`<h2>${x.id?'ویرایش کارت':'کارت جدید'}</h2><label>عنوان کارت<input id="cTitle" value="${esc(x.title)}"></label><label>شماره ۱۶ رقمی<input id="cNumber" maxlength="16" value="${esc(x.number)}"></label><label>صاحب کارت<input id="cHolder" value="${esc(x.holder)}"></label><button class="primary wide" onclick="saveCard(${x.id||0})">ذخیره کارت</button>`)}async function saveCard(id){let number=$('#cNumber').value.replaceAll(' ','');if(number.length!==16||!/^\\d+$/.test(number))return toast('شماره کارت باید ۱۶ رقم باشد',false);await api(id?'/api/cards/'+id:'/api/cards',{method:id?'PUT':'POST',body:JSON.stringify({title:$('#cTitle').value,number,holder:$('#cHolder').value,is_active:true})});closeModal();toast('کارت ذخیره شد');cards()}async function toggleCard(id){await api('/api/cards/'+id+'/toggle',{method:'POST'});toast('وضعیت کارت تغییر کرد');cards()}async function removeCard(id){if(confirm('حذف کامل کارت انجام شود؟')){await api('/api/cards/'+id,{method:'DELETE'});toast('کارت حذف شد');cards()}}
async function users(){let a=await api('/api/users');$('#view').innerHTML=`<div class="toolbar"><div><span class="eyebrow">AUDIENCE</span><h2>کاربران</h2></div><span class="counter">${a.length} کاربر</span></div><div class="panel table-wrap"><table><thead><tr><th>کاربر</th><th>شناسه</th><th>تاریخ عضویت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${a.map(x=>`<tr><td><b>${esc(x.full_name)}</b><small>@${esc(x.username||'ندارد')}</small></td><td>${x.id}</td><td>${esc(x.joined_at||'')}</td><td><span class="tag ${x.is_blocked?'off':'on'}">${x.is_blocked?'مسدود':'فعال'}</span></td><td><button class="mini" onclick="toggleUser(${x.id})">${x.is_blocked?'رفع مسدودی':'مسدود کردن'}</button></td></tr>`).join('')||`<tr><td colspan="5">${empty('کاربری ثبت نشده')}</td></tr>`}</tbody></table></div>`}async function toggleUser(id){await api('/api/users/'+id+'/toggle',{method:'POST'});toast('وضعیت کاربر تغییر کرد');users()}
async function support(){let a=await api('/api/support');$('#supportBadge').textContent=a.filter(x=>x.status==='open').length||'';$('#view').innerHTML=`<div class="toolbar"><div><span class="eyebrow">INBOX</span><h2>صندوق پشتیبانی</h2></div><span class="counter">${a.filter(x=>x.status==='open').length} باز</span></div><div class="ticket-list">${a.map(x=>`<article class="ticket ${x.status==='closed'?'closed':''}"><div class="ticket-head"><b>${esc(x.full_name||x.user_id)}</b><span>${esc(x.created_at)}</span></div><p>${esc(x.content)}</p><div><button class="mini" onclick="replyUser(${x.user_id})">پاسخ در ربات</button><button class="mini" onclick="closeTicket(${x.id})">بستن تیکت</button></div></article>`).join('')||empty('پیام پشتیبانی ندارید')}</div>`}async function closeTicket(id){await api('/api/support/'+id+'/close',{method:'POST'});toast('تیکت بسته شد');support()}function replyUser(id){modal(`<h2>ارسال پاسخ</h2><p class="sub">پاسخ از طریق ربات برای کاربر ${id} ارسال می‌شود.</p><textarea id="replyText" placeholder="متن پاسخ"></textarea><button class="primary wide" onclick="sendReply(${id})">ارسال پاسخ</button>`)}async function sendReply(id){await api('/api/broadcast',{method:'POST',body:JSON.stringify({text:$('#replyText').value})});closeModal();toast('پاسخ ارسال شد')}
async function admins(){let a=await api('/api/admins');$('#view').innerHTML=`<div class="toolbar"><div><span class="eyebrow">ACCESS</span><h2>مدیران و دسترسی‌ها</h2></div><button class="primary" onclick="adminForm()">＋ افزودن مدیر</button></div><div class="panel table-wrap"><table><thead><tr><th>شناسه</th><th>عنوان</th><th>دسترسی‌ها</th><th>عملیات</th></tr></thead><tbody>${a.map(x=>`<tr><td>${x.user_id}</td><td>${esc(x.title)}</td><td><span class="permissions">${esc(x.permissions)}</span></td><td><button class="mini danger" onclick="removeAdmin(${x.user_id})">حذف</button></td></tr>`).join('')||`<tr><td colspan="4">${empty('مدیری ثبت نشده')}</td></tr>`}</tbody></table></div>`}function adminForm(){modal(`<h2>افزودن مدیر</h2><label>شناسه عددی کاربر<input id="aId" type="number"></label><label>عنوان<input id="aTitle" value="ادمین"></label><label>دسترسی‌ها<input id="aPerm" value="products,orders,support,broadcast,settings"></label><button class="primary wide" onclick="saveAdmin()">ذخیره مدیر</button>`)}async function saveAdmin(){await api('/api/admins',{method:'POST',body:JSON.stringify({user_id:+$('#aId').value,title:$('#aTitle').value,permissions:$('#aPerm').value})});closeModal();toast('مدیر ذخیره شد');admins()}async function removeAdmin(id){if(confirm('مدیر حذف شود؟')){await api('/api/admins/'+id,{method:'DELETE'});toast('مدیر حذف شد');admins()}}
async function channels(){let a=await api('/api/channels');$('#view').innerHTML=`<div class="toolbar"><div><span class="eyebrow">GATEKEEPER</span><h2>عضویت اجباری</h2></div><button class="primary" onclick="channelForm()">＋ افزودن کانال</button></div><div class="card-grid">${a.map(x=>`<article class="channel"><b>${esc(x.title)}</b><small>${esc(x.chat_id)}</small><a href="${esc(x.invite_link)}" target="_blank">لینک عضویت ↗</a><button class="mini danger" onclick="removeChannel(${x.id})">حذف</button></article>`).join('')||empty('کانالی ثبت نشده')}</div>`}function channelForm(){modal(`<h2>افزودن کانال یا گروه</h2><label>شناسه چت<input id="chId" placeholder="-100..."></label><label>نام نمایشی<input id="chTitle"></label><label>لینک عضویت<input id="chLink" placeholder="https://t.me/..."></label><button class="primary wide" onclick="saveChannel()">ذخیره کانال</button>`)}async function saveChannel(){await api('/api/channels',{method:'POST',body:JSON.stringify({chat_id:$('#chId').value,title:$('#chTitle').value,invite_link:$('#chLink').value,is_active:true})});closeModal();toast('کانال ذخیره شد');channels()}async function removeChannel(id){if(confirm('کانال حذف شود؟')){await api('/api/channels/'+id,{method:'DELETE'});toast('کانال حذف شد');channels()}}
async function menu(){let x=await api('/api/menu');$('#view').innerHTML=`<div class="toolbar"><div><span class="eyebrow">EXPERIENCE</span><h2>طراحی منوی اصلی</h2></div><button class="primary" onclick="saveMenu()">ذخیره تغییرات</button></div><div class="menu-editor">${Object.entries(x).sort((a,b)=>a[1].order-b[1].order).map(([k,v])=>`<div class="menu-row"><span class="drag">⠿</span><b>${esc(k)}</b><input id="ml_${k}" value="${esc(v.label)}"><select id="mc_${k}"><option value="danger" ${v.color==='danger'?'selected':''}>قرمز</option><option value="success" ${v.color==='success'?'selected':''}>سبز</option><option value="primary" ${v.color==='primary'?'selected':''}>آبی</option></select><input id="mo_${k}" type="number" min="1" max="6" value="${v.order}"></div>`).join('')}</div>`}async function saveMenu(){let x=await api('/api/menu');Object.keys(x).forEach(k=>x[k]={label:$('#ml_'+k).value,color:$('#mc_'+k).value,order:+$('#mo_'+k).value});await api('/api/menu',{method:'PUT',body:JSON.stringify({config:x})});toast('منوی اصلی ذخیره شد');menu()}
async function broadcast(){modal(`<h2>پیام همگانی</h2><p class="sub">پیام برای کاربران فعال ارسال می‌شود.</p><textarea id="broadcastText" placeholder="متن پیام..."></textarea><button class="primary wide" onclick="sendBroadcast()">ارسال همگانی</button>`)}async function sendBroadcast(){let r=await api('/api/broadcast',{method:'POST',body:JSON.stringify({text:$('#broadcastText').value})});closeModal();toast(`${r.sent} پیام ارسال شد`)}async function system(){$('#view').innerHTML=`<div class="toolbar"><div><span class="eyebrow">SYSTEM</span><h2>سیستم و پشتیبان‌گیری</h2></div></div><div class="system-grid"><div class="panel"><h3>پشتیبان‌گیری</h3><p class="sub">یک نسخه کامل از دیتابیس دریافت کنید.</p><a class="primary btn" href="/api/backup">⇩ دانلود بکاپ</a></div><div class="panel"><h3>بازگردانی</h3><p class="sub">فایل SQLite را انتخاب کنید.</p><input id="restoreFile" type="file" accept=".sqlite3,.sqlite,.db"><button class="primary" onclick="restore()">بازگردانی دیتابیس</button></div><div class="panel"><h3>پیام همگانی</h3><p class="sub">ارسال اطلاعیه برای کاربران فعال.</p><button class="primary" onclick="broadcast()">↗ ساخت پیام</button></div></div>`}async function restore(){let f=$('#restoreFile').files[0];if(!f)return toast('فایل را انتخاب کنید',false);let fd=new FormData();fd.append('file',f);let r=await fetch('/api/restore',{method:'POST',body:fd});if(!r.ok)return toast('بازگردانی انجام نشد',false);toast('دیتابیس بازگردانی شد')}
function modal(body){let x=document.createElement('div');x.className='modal-back';x.innerHTML=`<div class="modal"><button class="modal-close" onclick="closeModal()">×</button>${body}</div>`;document.body.appendChild(x)}function closeModal(){document.querySelector('.modal-back')?.remove()}async function logout(){await fetch('/api/logout',{method:'POST'});location.href='/panel'}load();
</script>'''
